package com.villofarm.controller;
import com.villofarm.dto.OrderDtos.StatusRequest;import com.villofarm.model.CustomerOrder;import com.villofarm.model.OrderStatus;import com.villofarm.model.Product;import com.villofarm.repository.OrderRepository;import com.villofarm.repository.ProductRepository;import jakarta.validation.Valid;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import java.util.List;
@RestController @RequestMapping("/api/admin") public class AdminController {private final ProductRepository products;private final OrderRepository orders;public AdminController(ProductRepository products,OrderRepository orders){this.products=products;this.orders=orders;}@GetMapping("/products")public List<Product> products(){return products.findAll();}@PostMapping("/products")@ResponseStatus(HttpStatus.CREATED)public Product create(@Valid @RequestBody Product product){product.setId(null);return products.save(product);}@PutMapping("/products/{id}")public Product update(@PathVariable Long id,@Valid @RequestBody Product input){if(!products.existsById(id))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Product not found");input.setId(id);return products.save(input);}@DeleteMapping("/products/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)public void delete(@PathVariable Long id){var product=products.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Product not found"));product.setActive(false);products.save(product);}@GetMapping("/orders")public List<CustomerOrder> orders(){return orders.findAllByOrderByCreatedAtDesc();}@PatchMapping("/orders/{id}/status")public CustomerOrder status(@PathVariable Long id,@RequestBody StatusRequest request){var order=orders.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Order not found"));try{order.setStatus(OrderStatus.valueOf(request.status()));}catch(IllegalArgumentException e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Unknown order status");}return orders.save(order);}}
